from collections.abc import Callable


def scripted(*decisions: dict) -> Callable[[list[dict]], dict]:
    """A fake model that returns decisions in order and records each call's message contents in .seen."""
    queue = list(decisions)
    seen: list[list[str]] = []

    def model(messages: list[dict]) -> dict:
        seen.append([m["content"] for m in messages])
        return queue.pop(0)

    model.seen = seen  # type: ignore[attr-defined]
    return model

